SELECT FROM builtin_skills s WHERE s.deleted_at IS NULL AND (strpos(lower(display_title), lower(#{query.Query})) > 0 OR strpos(lower(external_id), lower(#{query.Query})) > 0)
AND listed AND NOT listed AND latest_version IS NULL
ORDER BY created_at DESC, uuid DESC LIMIT #{query.Limit} OFFSET #{query.Offset}
